window.ScripturaLexicons.DGP.entriesHtml += "<article id=\"entry-dgp-9301\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαζεύγνυμι</h1><div class=\"entry-meta\"><span>DGP · ordem 783 na letra δ · nº geral 9301</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 afastar; desunir; dissolver ♦ méd. 2 se­parar-se; divorciar-se.</p></section></article>\n<article id=\"entry-dgp-9302\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαζευκτικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 784 na letra δ · nº geral 9302</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">disjuntivo. 〈διαζεύγνυμι〉</p></section></article>\n<article id=\"entry-dgp-9303\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διάζευξις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 785 na letra δ · nº geral 9303</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 disjunção; separação; desunião 2 Mús. disjunção de dois tetracordes 3 Gram. disjunção. 〈διαζεύγνυμι〉</p></section></article>\n<article id=\"entry-dgp-9304\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαζωγραφέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 786 na letra δ · nº geral 9304</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pintar de diversas cores; pintar intei­ramente.</p></section></article>\n<article id=\"entry-dgp-9305\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διάζωμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 787 na letra δ · nº geral 9305</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cintura 2 calção (para esporte) 3 Arquit. friso; cornija 4 diafragma 5 linha de separação; separação 6 faixa de terra; istmo. 〈διαζώννυμι〉</p></section></article>\n<article id=\"entry-dgp-9306\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαζώννυμι</h1><div class=\"entry-meta\"><span>DGP · ordem 788 na letra δ · nº geral 9306</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διαζέσω etc.) 1 envolver com uma cin­ta; cingir; envolver ♦ méd. 2 atar à cintura.</p></section></article>\n<article id=\"entry-dgp-9307\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαζώω</h1><div class=\"entry-meta\"><span>DGP · ordem 789 na letra δ · nº geral 9307</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só impf. διέζωον) = διαζάω.</p></section></article>\n<article id=\"entry-dgp-9308\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διάημι</h1><div class=\"entry-meta\"><span>DGP · ordem 790 na letra δ · nº geral 9308</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. 3ª sing. διάει) soprar através de, gen. ou ac.</p></section></article>\n<article id=\"entry-dgp-9309\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαθάλπω</h1><div class=\"entry-meta\"><span>DGP · ordem 791 na letra δ · nº geral 9309</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(part. pres. διαθάλπων) aquecer suavemente.</p></section></article>\n<article id=\"entry-dgp-9310\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαθαρρέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 792 na letra δ · nº geral 9310</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(part. pres. fem. διαθαρροῦσα) tomar coragem; ter confiança.</p></section></article>\n<article id=\"entry-dgp-9311\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαθεάομαι-ῶμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 793 na letra δ · nº geral 9311</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">examinar a fundo; examinar bem, ac. ou or. relat. ou inter. indir.</p></section></article>\n<article id=\"entry-dgp-9312\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαθειόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 794 na letra δ · nº geral 9312</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. 3ª sing. διεθείωσεν) espalhar vapor de enxofre na casa; purificar com enxofre.</p></section></article>\n<article id=\"entry-dgp-9313\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαθερμαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 795 na letra δ · nº geral 9313</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aquecer; esquentar.</p></section></article>\n<article id=\"entry-dgp-9314\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διάθερμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 796 na letra δ · nº geral 9314</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 quente 2 quente; ardente (tempe­ramento).</p></section></article>\n<article id=\"entry-dgp-9315\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διάθεσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 797 na letra δ · nº geral 9315</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de pôr em ordem; arranjo; disposição 2 organização (de instituição) 3 compo­sição; arranjo literário ou artístico 4 arte de repre­sentar; representação; exposição; descrição 5 descrição geográfica 6 argumento de obra dramática 7 dispo­sição testamentária 8 facilidade para dispor de algo, dat. 9 disposição; maneira de ser do corpo ou da alma; forma; aspecto 10 disposição em rel. a alguém 11 Gram. comportamento de um verbo; voz. 〈διατίθημι〉</p></section></article>\n<article id=\"entry-dgp-9316\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαθέτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 798 na letra δ · nº geral 9316</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aquele que coloca em ordem; or­denador. 〈διατίθημι〉</p></section></article>\n<article id=\"entry-dgp-9317\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαθέω</h1><div class=\"entry-meta\"><span>DGP · ordem 799 na letra δ · nº geral 9317</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διαθεύσομαι etc.) 1 correr por todos os lados; difundir-se 2 (astro) errar; vagar 3 disputar uma corrida; rivalizar na corrida com alguém, dat. ou πρός e ac.</p></section></article>\n<article id=\"entry-dgp-9318\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαθήκη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 800 na letra δ · nº geral 9318</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 arranjo; disposição; ordenação 2 dis­posição testamentária 3 pacto; convenção; acordo 4 crist. testamento: ἡ παλαιὰ δ., ἡ καινὴ ou νέα δ. o Antigo Testamento; o Novo Testamento. 〈διατίθημι〉</p></section></article>\n<article id=\"entry-dgp-9319\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαθηριόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 801 na letra δ · nº geral 9319</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(pres. pas. 3ª sing. διαθηριοῦται) tornar-se totalmente selvagem.</p></section></article>\n<article id=\"entry-dgp-9320\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαθλάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 802 na letra δ · nº geral 9320</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fazer em pedaços.</p></section></article>\n<article id=\"entry-dgp-9321\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαθλέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 803 na letra δ · nº geral 9321</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">lutar com todas as forças; lutar até o fim. 〈διά, ἀθλέω〉</p></section></article>\n<article id=\"entry-dgp-9322\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαθολόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 804 na letra δ · nº geral 9322</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(part. aor. pas. fem. gen. διαθολωθείσης) remexer a lama; turvar.</p></section></article>\n<article id=\"entry-dgp-9323\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαθορυβέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 805 na letra δ · nº geral 9323</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 perturbar; transtornar alguém 2 fazer estardalhaço.</p></section></article>\n<article id=\"entry-dgp-9324\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαθρέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 806 na letra δ · nº geral 9324</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">examinar com atenção. 〈διά, ἀθρέω〉</p></section></article>\n<article id=\"entry-dgp-9325\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαθρυλέομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 807 na letra δ · nº geral 9325</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 espalhar rumor: διετεθρύλητο ὡς xen. havia um rumor espalhado de que... 2 ensurdecer com falas ou gritos: διαθρυλούμενος ὑπό τινος xen. ensurdecido, aturdido por alguém, διατεθρύλημαι ἀκούων plat. estou atordoado de ouvir.</p></section></article>\n<article id=\"entry-dgp-9326\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαθρύπτω</h1><div class=\"entry-meta\"><span>DGP · ordem 808 na letra δ · nº geral 9326</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor.2 pas. διετρύφην; perf. pas. διατέτρυμμαι) 1 fazer em pedaços; quebrar 2 enfraquecer; delibitar: διατεθρυμμένος τὰ ὦτα κολακείας dem. tendo os ouvidos enfraquecidos pela lisonja 3 efeminar ♦ méd. 4 fazer gestos afetados: διαθρύπτεται teócr. comporta-se com afetação; faz dengos.</p></section></article>\n<article id=\"entry-dgp-9327\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαί</h1><div class=\"entry-meta\"><span>DGP · ordem 809 na letra δ · nº geral 9327</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">διά.</p></section></article>\n<article id=\"entry-dgp-9328\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαιθριάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 810 na letra δ · nº geral 9328</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) tornar-se claro e sereno (tempo).</p></section></article>\n<article id=\"entry-dgp-9329\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίαιθρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 811 na letra δ · nº geral 9329</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">claro e sereno. 〈διά, αἰθήρ〉</p></section></article>\n<article id=\"entry-dgp-9330\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίαιμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 812 na letra δ · nº geral 9330</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ensanguentado. 〈διά, αἷμα〉</p></section></article>\n<article id=\"entry-dgp-9331\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίαινε, διαίνετο</h1><div class=\"entry-meta\"><span>DGP · ordem 813 na letra δ · nº geral 9331</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">impf. at. e pas. 3ª sing. poét. de διαίνω.</p></section></article>\n<article id=\"entry-dgp-9332\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 814 na letra δ · nº geral 9332</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. ἐδίανα) 1 molhar; umedecer 2 molhar de lágrimas; chorar alguém ♦ méd. 3 molhar de lágrimas 4 molhar-se; banhar-se.</p></section></article>\n<article id=\"entry-dgp-9333\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαίρεσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 815 na letra δ · nº geral 9333</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 divisão; distribuição; partilha (de bens) 2 distinção; diversidade; distinção lógica 3 divisão em partes; divisão em gêneros; divisão em espécies 4 divisibilidade 5 divisão em tropas 6 Medic. corte; cirurgia. 〈διαιρέω〉</p></section></article>\n<article id=\"entry-dgp-9334\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαιρετέος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 816 na letra δ · nº geral 9334</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de διαιρέω.</p></section></article>\n<article id=\"entry-dgp-9335\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαιρετικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 817 na letra δ · nº geral 9335</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 divisível; decomponível 2 capaz de dividir, de decompor 3 que concerne a divisão, a decomposição. 〈διαιρέω〉</p></section></article>\n<article id=\"entry-dgp-9336\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαιρετικῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 818 na letra δ · nº geral 9336</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. dividindo; decompondo.</p></section></article>\n<article id=\"entry-dgp-9337\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαιρετός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 819 na letra δ · nº geral 9337</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 divisível; separável 2 dividido; se­parado; distribuído 3 que se pode distinguir, deter­minar. 〈διαιρέω〉</p></section></article>\n<article id=\"entry-dgp-9338\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαιρέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 820 na letra δ · nº geral 9338</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διαιρήσω, aor.2 διεῖλον, perf. διῄρηκα etc.) 1 dividir; separar em pedaços ou partes: τὸ πᾶν πλῆθος ἐκ τιμημάτων διεῖλεν εἰς τέτταρα τέλη artt. dividiu toda a multidão em quatro classes de acordo com as posses 2 quebrar; despedaçar: τὴν πυλίδα διήρουν tuc. quebraram a portinhola 3 distinguir por divisões ou classificações: δ. τυραννίδος εἴδη δύο artt. distinguir dois tipos de tirania 4 determinar; resolver; decidir; julgar: διαφορὰς δ. her. decidir pendências, δ. τὰ ἀμφίλογα xen. resolver os casos duvidosos, κλήρῳ δ. τὸν νικῶντα plat. determinar pela sorte o vencedor ♦ méd. 5 dividir; partilhar entre si: διελόμενοι κατὰ πόλεις τὸ ἔργον tuc. tendo dividido a tarefa entre as cidades 6 distinguir; classificar: διῄρητο ξύμπαν τὸ ζῷον τῷ τιθασῷ καὶ ἀγρίῳ plat. dividiu o conjunto dos seres vivos em domésticos e selvagens 7 explicar; definir: ἴθι δή μοι διελοῦ τάδε plat. vamos, explica-me isto. 〈διά, αἱρέω〉</p></section></article>\n<article id=\"entry-dgp-9339\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαίρω</h1><div class=\"entry-meta\"><span>DGP · ordem 821 na letra δ · nº geral 9339</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διαρῶ, aor. διῆρα, perf. διῆρκα; part. perf. pas. διηρμένος) 1 elevar; levantar ao alto 2 separar; afastar: τὸν πόλεμον διάρας ἀπὸ τῆς θαλάσσης plut. tendo afastado do mar a guerra, δ. τὸ στόμα dem. abrir a boca; διηρμένος d.h. que tem a boca escancarada, i.e., que se expressa com grandiloqüência 3 lançar-se para além de; atravessar, ac.: δ. τὸ πέλαγος artt. atravessar o mar 4 exagerar ♦ méd. 5 levantar; erguer: δ. τὴν βακτηρίαν plut. o bastão 6 erguer separando: διαράμενος [τὰ σκέλη] teofr. tendo separado as pernas, i.e., tendo caminhado a passos largos 7 elevar-se 8 encarregar-se de; assumir, ac. 〈διά, αἴρω〉</p></section></article>\n<article id=\"entry-dgp-9340\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαισθάνομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 822 na letra δ · nº geral 9340</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor.2 διῃσθόμην etc.) perceber com nitidez; distinguir. 〈διά, αἰσθάνομαι〉</p></section></article>\n<article id=\"entry-dgp-9341\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαΐσσω,</h1><div class=\"entry-meta\"><span>DGP · ordem 823 na letra δ · nº geral 9341</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. διᾴσσω ou διᾴττω e διάττω (fut. διᾴξω, aor. διῄξα, perf. desus.) 1 lançar-se; agitar: σπασμὸς διῆξε πλευρῶν sóf. a convulsão agitou meus flancos 2 lançar-se de todos os lados, saltar: πυρὸς λαμπρὸν διάϊσσεν μένος baq. o ardor brilhante do fogo saltava 3 lançar-se através de, ac.: ὄρεα διᾴσσει sóf. salta através os montes 4 (som) repercutir: ἀχὼ διῇξεν ἄντρων μυχόν ésql. o eco retiniu até o fundo das cavernas. 〈διά, ἀΐσσω〉</p></section></article>\n<article id=\"entry-dgp-9342\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαιστόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 824 na letra δ · nº geral 9342</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. 3ª sing. διηΐστωσε) fazer desaparecer; aniquilar. 〈διά, ἀϊστόω〉</p></section></article>\n<article id=\"entry-dgp-9343\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαισχύνομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 825 na letra δ · nº geral 9343</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(part. aor. διαισχυνθείς) cobrir-se de vergonha. 〈διά, αἰσχύνομαι〉</p></section></article>\n<article id=\"entry-dgp-9344\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">δίαιτα, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 826 na letra δ · nº geral 9344</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 gênero de vida; modo de viver; hábitos de vida; condição de vida; vida: δίαιταν τῆς ζόης μεταβάλλειν her. mudar o modo de viver 2 tipo de vida prescrito pelo médico; regime 3 residência; estada: δίαιταν ἔχειν παρά τινι her. viver junto de alguém 4 local de moradia; casa; toca (de animal) 5 Jur. arbitragem: δίαιταν ἐπιτρέψαι τοῖς φίλοις lís. confiar a arbitragem aos amigos 6 ofício de árbitro 7 discussão; investigação.</p></section></article>\n<article id=\"entry-dgp-9345\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαιτάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 827 na letra δ · nº geral 9345</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. διῄτων, fut. διαιτήσω, aor. διήτησα, perf. δεδιῄτηκα; pas. impf. διῃτώμην, fut. διαιτήσομαι, aor. διητήθην, perf. δεδιήτημαι) 1 submeter a um gênero de vida; submeter a um tratamento médico; cuidar de, ac. 2 ser árbitro para alguém, dat. 3 arbitrar; decidir em arbitragem algo, ac. ou or. inf. 4 decidir como árbitro; apaziguar; conciliar 5 tard. governar; dirigir; administrar 6 tard. reconciliar uma pessoa, ac., com outra, dat. ♦ méd. pas. 7 viver; ter vida costumeira: δ. ἀνειμένως tuc. viver despreocupadamente 8 residir; morar: δ. ἄνω, δ. κάτω lís. morar no andar de cima, morar no térreo, δ. ἐπ᾽ ἀγροῦ her., δ. ἐν τοῖς ἀγροῖς tuc. morar no campo 9 submeter-se a um regime, a um tratamento. 〈δίαιτα〉</p></section></article>\n<article id=\"entry-dgp-9346\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαίτημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 828 na letra δ · nº geral 9346</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 gênero de vida; regra de vida 2 alimentação; nutrição 3 gênero de vida de um povo; cos­tumes; instituições 4 domicílio; habitação. 〈διαιτάω〉</p></section></article>\n<article id=\"entry-dgp-9347\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαιτητήριον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 829 na letra δ · nº geral 9347</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 morada; residência; habitação 2 quarto. 〈διαιτάω〉</p></section></article>\n<article id=\"entry-dgp-9348\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διαιτητής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 830 na letra δ · nº geral 9348</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">árbitro; juiz. 〈διαιτάω〉</p></section></article>\n<article id=\"entry-dgp-9349\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακαής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 831 na letra δ · nº geral 9349</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">muito quente; abrasador; ardente. 〈διά, καίω〉</p></section></article>\n<article id=\"entry-dgp-9350\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακαθαίρω</h1><div class=\"entry-meta\"><span>DGP · ordem 832 na letra δ · nº geral 9350</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 purificar; purgar 2 podar (árvores) 3 es­clarecer; explicar; definir ♦ méd. 4 purificar; depurar selecionando.</p></section></article>\n<article id=\"entry-dgp-9351\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακαθέζομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 833 na letra δ · nº geral 9351</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ocupar lugar 2 sentar-se aqui e lá 3 sen­tar-se.</p></section></article>\n<article id=\"entry-dgp-9352\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακάθημαι</h1><div class=\"entry-meta\"><span>DGP · ordem 834 na letra δ · nº geral 9352</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 (exército) ocupar seu posto 2 (corvo) em­poleirar-se.</p></section></article>\n<article id=\"entry-dgp-9353\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακαθίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 835 na letra δ · nº geral 9353</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(part. aor. διακαθίσας) 1 fazer sentar à parte; separar 2 at. e méd. ir à latrina.</p></section></article>\n<article id=\"entry-dgp-9354\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακαίω</h1><div class=\"entry-meta\"><span>DGP · ordem 836 na letra δ · nº geral 9354</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(part. perf. pas. διακεκαυμένος) 1 queimar; esquentar em excesso; incendiar; tornar abrasante 2 Medic. queimar; cauterizar 3 inflamar; excitar.</p></section></article>\n<article id=\"entry-dgp-9355\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακαλύπτω</h1><div class=\"entry-meta\"><span>DGP · ordem 837 na letra δ · nº geral 9355</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 descobrir; deixar ver; revelar ♦ méd. 2 abrir; entreabrir, ac.</p></section></article>\n<article id=\"entry-dgp-9356\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακαραδοκέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 838 na letra δ · nº geral 9356</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aguardar com ansiedade, ac.</p></section></article>\n<article id=\"entry-dgp-9357\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακαρτερέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 839 na letra δ · nº geral 9357</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 mostrar vigor até o fim; perseverar; resistir; persistir em algo, ἐν e dat. ou com part. 2 suportar até o fim, ac. ou inf. 3 δ. ἑαυτοῦ permanecer senhor de si mesmo.</p></section></article>\n<article id=\"entry-dgp-9358\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακατελέγχομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 840 na letra δ · nº geral 9358</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. refutar vitoriosamente alguém, dat.</p></section></article>\n<article id=\"entry-dgp-9359\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακατέχω</h1><div class=\"entry-meta\"><span>DGP · ordem 841 na letra δ · nº geral 9359</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 conter; deter 2 fazer prolongar-se 3 man­ter a posse de; ocupar; habitar.</p></section></article>\n<article id=\"entry-dgp-9360\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διάκαυσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 842 na letra δ · nº geral 9360</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 Medic. cauterização completa 2 cinzas. 〈διακαίω〉</p></section></article>\n<article id=\"entry-dgp-9361\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακέαται</h1><div class=\"entry-meta\"><span>DGP · ordem 843 na letra δ · nº geral 9361</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. pres. jôn. de διάκειμαι.</p></section></article>\n<article id=\"entry-dgp-9362\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διάκειμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 844 na letra δ · nº geral 9362</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διακείσομαι etc.) 1 encontrar-se posto; encontrar-se colocado 2 (pessoa) encontrar-se em certa condição, com adv.: δ. κακῶς plat. encontrar-se mal disposto, δ. ἀσελγῶς lís. ser insolente, δ. δυσμενῶς isócr. ter disposições mal intencionadas, δ. φιλικῶς xen. ser amigo de, δ. ὑπόπτως tuc. ser alvo de suspeita da parte de alguém, dat., a propósito de alguém ou algo, dat. ou πρός e ac. 3 impes. está estabelecido; está decidido; está acertado: νόμῳ ὡς διάκειται pínd. como está prescrito pela lei, ἐπὶ διακειμένοις μουναμαχῆσαι her. participar de um combate singular.</p></section></article>\n<article id=\"entry-dgp-9363\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακείρω</h1><div class=\"entry-meta\"><span>DGP · ordem 845 na letra δ · nº geral 9363</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tosar; raspar 2 fazer desaparecer; destruir 3 espoliar; despojar 4 infringir.</p></section></article>\n<article id=\"entry-dgp-9364\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακελεύομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 846 na letra δ · nº geral 9364</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fazer uma prescrição; ordenar; reco­mendar a alguém, dat., algo, ac. ou inf. ou or. (ὅπως) 2 fazer uma exortação; encorajar alguém, dat.: ἀλλή­λοις διεκελεύοντο xen. encorajavam-se uns aos outros, δ. ἑαυτῷ τολμᾶν xen. encorajar-se a si próprio para ousar 3 advertir; informar alguém, dat., de algo, περί e gen.</p></section></article>\n<article id=\"entry-dgp-9365\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακελευσμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 847 na letra δ · nº geral 9365</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">exortação; encorajamento. 〈διακελεύομαι〉</p></section></article>\n<article id=\"entry-dgp-9366\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διάκενος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 848 na letra δ · nº geral 9366</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 vazio; oco; desguarnecido 2 poroso; sem consistência; leve 3 esguio; delgado; magro 4 vão; inútil ♦ τὸ διάκενον 5 espaço desguarnecido; brecha ♦ τὰ διάκενα 6 cavidades. 〈διά, κενός〉</p></section></article>\n<article id=\"entry-dgp-9367\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακέρσαι</h1><div class=\"entry-meta\"><span>DGP · ordem 849 na letra δ · nº geral 9367</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor. ép. de διακείρω.</p></section></article>\n<article id=\"entry-dgp-9368\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακηρυκεύομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 850 na letra δ · nº geral 9368</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">enviar um arauto a alguém, πρός e ac.</p></section></article>\n<article id=\"entry-dgp-9369\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακηρύσσω</h1><div class=\"entry-meta\"><span>DGP · ordem 851 na letra δ · nº geral 9369</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. διακηρύξω etc.) 1 levar a leilão pelo arauto público 2 at. e méd. enviar um arauto 3 negociar por intermédio de um arauto 4 fazer o arauto anunciar ou declarar guerra.</p></section></article>\n<article id=\"entry-dgp-9370\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακινδυνεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 852 na letra δ · nº geral 9370</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 expor-se a perigo por alguém, ὑπέρ, πρό ou περί e gen. 2 fazer esforço supremo contra algo, πρός ou ἐς e ac. 3 correr o risco de, inf. ou or. inf. ♦ pas. 4 ser exposto a riscos máximos: διακεκινδυνευμένα φάρμακα isócr. remédios extremos.</p></section></article>\n<article id=\"entry-dgp-9371\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακινέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 853 na letra δ · nº geral 9371</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 mover em diversos sentidos suavemente uma articulação 2 agitar; perturbar 3 excitar; comover ♦ méd. 4 mover-se de um lado para outro.</p></section></article>\n<article id=\"entry-dgp-9372\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακλαπέν</h1><div class=\"entry-meta\"><span>DGP · ordem 854 na letra δ · nº geral 9372</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. aor.2 pas. n. de διακλέπτω.</p></section></article>\n<article id=\"entry-dgp-9373\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακλάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 855 na letra δ · nº geral 9373</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 quebrar em dois, ac. 2 quebrantar; debilitar; afeminar.</p></section></article>\n<article id=\"entry-dgp-9374\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακλείω</h1><div class=\"entry-meta\"><span>DGP · ordem 856 na letra δ · nº geral 9374</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 interditar; proibir: δ. χορηγίας τινί pol. proi­bir as coregias a alguém 2 excluir; afastar alguém, ac., de algum lugar, gen. ou ἀπό e gen.</p></section></article>\n<article id=\"entry-dgp-9375\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακλέπτω</h1><div class=\"entry-meta\"><span>DGP · ordem 857 na letra δ · nº geral 9375</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 subtrair; desviar; roubar 2 dissimular: δ. τοῖς λόγοις τὴν ἀλήθειαν dem. dissimular sob as palavras a verdade 3 preservar; livrar (da morte) ♦ méd. 4 esquivar-se; furtar-se a; abster-se de, com τοῦ e inf.</p></section></article>\n<article id=\"entry-dgp-9376\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακληρόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 858 na letra δ · nº geral 9376</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 atribuir por meio de sorteio 2 escolher por meio de sorteio ♦ méd. 3 tirar a sorte; sortear ♦ pas. 4 caber por sorte.</p></section></article>\n<article id=\"entry-dgp-9377\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακλίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 859 na letra δ · nº geral 9377</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 distanciar-se de; afastar-se de, gen. ou ἀπό e gen. 2 evitar; esquivar-se de; escapar de, ac.</p></section></article>\n<article id=\"entry-dgp-9378\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διάκλισις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 860 na letra δ · nº geral 9378</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ação de esquivar-se; retirada; de­serção. 〈διακλίνω〉</p></section></article>\n<article id=\"entry-dgp-9379\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακλύζω</h1><div class=\"entry-meta\"><span>DGP · ordem 861 na letra δ · nº geral 9379</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 lavar inteiramente 2 banhar; inundar 3 Medic. purgar ♦ méd. 4 enxaguar bem.</p></section></article>\n<article id=\"entry-dgp-9380\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακναίω</h1><div class=\"entry-meta\"><span>DGP · ordem 862 na letra δ · nº geral 9380</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 espedaçar; rasgar com as unhas ou as garras 2 (fome, dor) dilacerar; esgotar; aniquilar 3 arranhar.</p></section></article>\n<article id=\"entry-dgp-9381\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακολακεύομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 863 na letra δ · nº geral 9381</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">rivalizar em adulação.</p></section></article>\n<article id=\"entry-dgp-9382\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακολλάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 864 na letra δ · nº geral 9382</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">colar; soldar.</p></section></article>\n<article id=\"entry-dgp-9383\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακομιδή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 865 na letra δ · nº geral 9383</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">transporte para, εἰς e ac.</p></section></article>\n<article id=\"entry-dgp-9384\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακομίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 866 na letra δ · nº geral 9384</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fazer passar; transportar alguém, ac., para algum lugar, εἰς e ac. 2 Medic. restabelecer; fortalecer; fazer recuperar a saúde ♦ méd. 3 transportar consigo.</p></section></article>\n<article id=\"entry-dgp-9385\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακονέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 867 na letra δ · nº geral 9385</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἐδιακόνουν, fut. διακονήσω, aor. ἐδιακόνησα, perf. δεδιακόνηκα) 1 ser servidor; desem­penhar a função de servidor de alguém ou junto de alguém, dat. ou παρά e dat., em função de algo, πρός e ac. 2 crist. ser diácono 3 preparar como bom servidor algo, ac., a alguém, dat.: τὰ καλῶς δεδιακονημένα dem. os bons serviços prestados 4 prestar socorro a alguém, dat. ♦ méd. 5 ser servidor de si mesmo; servir-se a si próprio algo, ac. 〈διάκονος〉</p></section></article>\n<article id=\"entry-dgp-9386\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακονία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 868 na letra δ · nº geral 9386</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 serviço; ministério; ofício de ser­vidor 2 execução de um dever, de deveres 3 col. o conjunto dos servidores 4 crist. serviço em beneficio dos pobres; esmola. 〈διάκονος〉</p></section></article>\n<article id=\"entry-dgp-9387\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακονικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 869 na letra δ · nº geral 9387</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de servidor; concernente aos servi­dores 2 apto a servir ♦ ἡ διακονική 3 a arte de servir. 〈διάκονος〉</p></section></article>\n<article id=\"entry-dgp-9388\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακονίομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 870 na letra δ · nº geral 9388</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 (cavalo) rolar na poeira 2 cobrir-se de poeira; preparar-se para o combate.</p></section></article>\n<article id=\"entry-dgp-9389\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διάκονος, ου (ὁ, ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 871 na letra δ · nº geral 9389</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 servo; serva 2 mensageiro 3 cúm­plice 4 crist. diácono; diaconisa ♦ adj. 5 que está a ser­viço de; útil; proveitoso.</p></section></article>\n<article id=\"entry-dgp-9390\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακοντίζομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 872 na letra δ · nº geral 9390</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 exercitar-se na luta com lança 2 lançar a lança. 〈διά, ἀκοντίζω〉</p></section></article>\n<article id=\"entry-dgp-9391\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακόντωσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 873 na letra δ · nº geral 9391</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">κόντωσις.</p></section></article>\n<article id=\"entry-dgp-9392\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακοπή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 874 na letra δ · nº geral 9392</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 talhe; ferida profunda 2 passagem estreita; istmo; canal 3 separação abrupta; ruptura; di­vórcio; litígio 4 refutação. 〈διακόπτω〉</p></section></article>\n<article id=\"entry-dgp-9393\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακοπτέον</h1><div class=\"entry-meta\"><span>DGP · ordem 875 na letra δ · nº geral 9393</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de διακόπτω.</p></section></article>\n<article id=\"entry-dgp-9394\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακόπτω</h1><div class=\"entry-meta\"><span>DGP · ordem 876 na letra δ · nº geral 9394</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fender profundamente; cortar em dois; cor­tar; ferir 2 abrir (passagem) 3 quebrar; romper (uma frente inimiga) 4 interromper.</p></section></article>\n<article id=\"entry-dgp-9395\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακορεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 877 na letra δ · nº geral 9395</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e διακορέω-ῶ deflorar. 〈διά, κόρη〉</p></section></article>\n<article id=\"entry-dgp-9396\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακορής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 878 na letra δ · nº geral 9396</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">totalmente saciado de, gen. 〈διά, κορέννυμι〉</p></section></article>\n<article id=\"entry-dgp-9397\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διάκορος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 879 na letra δ · nº geral 9397</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">saciado; saturado; enfastiado de, gen. 〈διακορής〉</p></section></article>\n<article id=\"entry-dgp-9398\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">∆ιακός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 880 na letra δ · nº geral 9398</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dos Dios, povo da Trácia. 〈∆ΐοι〉</p></section></article>\n<article id=\"entry-dgp-9399\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακόσιοι, αι, α</h1><div class=\"entry-meta\"><span>DGP · ordem 881 na letra δ · nº geral 9399</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">num. duzentos.</p></section></article>\n<article id=\"entry-dgp-9400\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">διακοσμέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 882 na letra δ · nº geral 9400</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 colocar em ordem; organizar; dispor: ἐς δεκάδας hom. dispor em grupos de dez ♦ méd. 2 pôr em ordem; ordenar minuciosamente 3 reorganizar.</p></section></article>\n";
